    return SemanticDocumentValidationResult(
      SemanticDocumentValidationCode.schemaMajorMismatch,
      '${value['schemaVersion']}',
    );
  }
  if (_major(value['dialectVersion']) !=
      _major(semanticDocumentDialectVersion)) {
    return SemanticDocumentValidationResult(
      SemanticDocumentValidationCode.dialectMajorMismatch,
      '${value['dialectVersion']}',
    );
  }
  if (value['canonicalizationVersion'] !=
      semanticDocumentCanonicalizationVersion) {
    return SemanticDocumentValidationResult(
      SemanticDocumentValidationCode.canonicalizationMismatch,
      '${value['canonicalizationVersion']}',
    );
  }
  if (value['offsetEncoding'] != semanticDocumentOffsetEncoding) {
    return SemanticDocumentValidationResult(
      SemanticDocumentValidationCode.offsetEncodingMismatch,
      '${value['offsetEncoding']}',
    );
  }
  final required = value['requiredCapabilities'];
  if (required is! List || required.any((id) => id is! String)) {
    return const SemanticDocumentValidationResult(
      SemanticDocumentValidationCode.invalidFieldType,
      'requiredCapabilities',
    );
  }
  final declared = required.cast<String>().toSet();
  for (final id in declared) {
    if (!semanticDocumentCapabilityIds.contains(id) ||
        !available.contains(id)) {
      return SemanticDocumentValidationResult(
        SemanticDocumentValidationCode.capabilityMissing,
        id,
      );
    }
  }
  final nodes = value['nodes'];
  if (nodes is! List) {
    return const SemanticDocumentValidationResult(
      SemanticDocumentValidationCode.invalidFieldType,
      'nodes',
    );
  }
  for (final raw in nodes) {
    if (raw is! Map<String, Object?>) {
      return const SemanticDocumentValidationResult(
        SemanticDocumentValidationCode.invalidFieldType,
        'node',
      );
