T? _enumByName<T extends Enum>(List<T> values, Object? raw) {
  if (raw is! String) return null;
  for (final value in values) {
    if (value.name == _wireToEnumName(raw)) return value;
  }
  return null;
}

String _wireToEnumName(String value) {
  final parts = value.split('_');
  return parts.first +
      parts
          .skip(1)
          .map((part) => part[0].toUpperCase() + part.substring(1))
          .join();
}

String _major(Object? value) {
  final text = value is String ? value : '';
  final dot = text.indexOf('.');
  return dot < 0 ? '' : text.substring(0, dot);
}

Map<String, Object?> _semanticObject(Object? value, String path) {
  if (value is Map<String, Object?>) return value;
  if (value is Map)
    return value.map((key, value) => MapEntry(key.toString(), value));
  throw FormatException('$path must be an object');
}

List<Object?> _semanticList(Object? value, String path) {
  if (value is List) return value.cast<Object?>();
  throw FormatException('$path must be a list');
}

String _semanticString(Object? value, String path) {
  if (value is String) return value;
  throw FormatException('$path must be a string');
}

int _semanticInt(Object? value, String path) {
  if (value is int) return value;
  throw FormatException('$path must be an integer');
}

T _semanticEnum<T extends Enum>(List<T> values, Object? raw, String path) {
  if (raw is String) {
    for (final value in values) {
      final snake = value.name.replaceAllMapped(
        RegExp(r'[A-Z]'),
        (m) => '_${m[0]!.toLowerCase()}',
      );
      if (value.name == raw || snake == raw) return value;
    }
  }
  throw FormatException('$path has an invalid enum value');
}

