        .asMap()
        .entries
        .map((e) => _lossFromWire(e.value, '$p.losses[${e.key}]'))
        .toList(),
    semanticFingerprint: _semanticString(
      m['semanticFingerprint'],
      '$p.semanticFingerprint',
    ),
    sourceAnchor: _sourceAnchorFromWire(m['sourceAnchor'], '$p.sourceAnchor'),
    diagnostics:
        (m['diagnostics'] == null
                ? const <Object?>[]
                : _semanticList(m['diagnostics'], '$p.diagnostics'))
            .asMap()
            .entries
            .map(
              (e) => _diagnosticFromWire(e.value, '$p.diagnostics[${e.key}]'),
            )
            .toList(),
    rawSlice: m['rawSlice'] as String?,
    rawSliceFingerprint: m['rawSliceFingerprint'] as String?,
    attributes: m['attributes'] == null
        ? const {}
        : _semanticObject(m['attributes'], '$p.attributes'),
    children:
        (m['children'] == null
                ? const <Object?>[]
                : _semanticList(m['children'], '$p.children'))
            .asMap()
            .entries
            .map((e) => _nodeFromWire(e.value, '$p.children[${e.key}]'))
            .toList(),
    inlines:
        (m['inlines'] == null
                ? const <Object?>[]
                : _semanticList(m['inlines'], '$p.inlines'))
            .asMap()
            .entries
            .map((e) => _inlineFromWire(e.value, '$p.inlines[${e.key}]'))
            .toList(),
  );
}

Map<String, Object?> _inlineToWire(SemanticInline v) => {
  'kind': v.kind.name,
  'start': v.start,
  'end': v.end,
  'attributes': v.attributes,
};
Map<String, Object?> _nodeToWire(SemanticNode v) => {
  'nodeId': v.nodeId,
  'kind': v.kind.name,
  'disposition': v.disposition.name.replaceAllMapped(
    RegExp(r'[A-Z]'),
    (m) => '_${m[0]!.toLowerCase()}',
  ),
  'policyVersion': v.policyVersion,
  'requiredCapabilities': v.requiredCapabilities,
  'losses': v.losses.map(_lossToWire).toList(),
  'semanticFingerprint': v.semanticFingerprint,
  'sourceAnchor': _sourceAnchorToWire(v.sourceAnchor),
  'diagnostics': v.diagnostics.map(_diagnosticToWire).toList(),
  'rawSlice': v.rawSlice,
  'rawSliceFingerprint': v.rawSliceFingerprint,
  'attributes': v.attributes,
  'children': v.children.map(_nodeToWire).toList(),
  'inlines': v.inlines.map(_inlineToWire).toList(),
};
DocumentEnvelope documentEnvelopeFromWire(
  Map<String, Object?> m, [
  String p = 'DocumentEnvelope',
]) => DocumentEnvelope(
  schemaVersion: _semanticString(m['schemaVersion'], '$p.schemaVersion'),
  dialectVersion: _semanticString(m['dialectVersion'], '$p.dialectVersion'),
  canonicalizationVersion: _semanticString(
    m['canonicalizationVersion'],
    '$p.canonicalizationVersion',
  ),
  offsetEncoding: _semanticString(m['offsetEncoding'], '$p.offsetEncoding'),
  nodes: _semanticList(m['nodes'], '$p.nodes')
      .asMap()
      .entries
      .map((e) => _nodeFromWire(e.value, '$p.nodes[${e.key}]'))
      .toList(),
  requiredCapabilities: _semanticList(
    m['requiredCapabilities'],
    '$p.requiredCapabilities',
  ).map((e) => _semanticString(e, p)).toList(),
  assets: _semanticObject(m['assets'], '$p.assets').map((k, v) {
    final a = _semanticObject(v, '$p.assets.$k');
    return MapEntry(
      k,
      SemanticAsset(
        id: _semanticString(a['id'], '$p.assets.$k.id'),
        attributes: a['attributes'] == null
            ? const {}
            : _semanticObject(a['attributes'], '$p.assets.$k.attributes'),
      ),
    );
  }),
  sourceMap: _semanticObject(
    m['sourceMap'],
    '$p.sourceMap',
  ).map((k, v) => MapEntry(k, _sourceAnchorFromWire(v, '$p.sourceMap.$k'))),
  policyVersion: _semanticString(m['policyVersion'], '$p.policyVersion'),
  losses: _semanticList(m['losses'], '$p.losses')
      .asMap()
      .entries
      .map((e) => _lossFromWire(e.value, '$p.losses[${e.key}]'))
      .toList(),
  semanticFingerprint: _semanticString(
    m['semanticFingerprint'],
    '$p.semanticFingerprint',
  ),
  canonicalDigest: _semanticString(m['canonicalDigest'], '$p.canonicalDigest'),
);
Map<String, Object?> documentEnvelopeToWire(DocumentEnvelope v) => {
  'schemaVersion': v.schemaVersion,
  'dialectVersion': v.dialectVersion,
  'canonicalizationVersion': v.canonicalizationVersion,
  'offsetEncoding': v.offsetEncoding,
  'nodes': v.nodes.map(_nodeToWire).toList(),
  'requiredCapabilities': v.requiredCapabilities,
  'assets': v.assets.map(
    (k, a) => MapEntry(k, {'id': a.id, 'attributes': a.attributes}),
  ),
  'sourceMap': v.sourceMap.map((k, a) => MapEntry(k, _sourceAnchorToWire(a))),
  'policyVersion': v.policyVersion,
  'losses': v.losses.map(_lossToWire).toList(),
  'semanticFingerprint': v.semanticFingerprint,
  'canonicalDigest': v.canonicalDigest,
};
